import{X as e,Y as t,ct as n,t as r}from"./chunks/framework.CaFWb3SA.js";var i=JSON.parse(`{"title":"调试命令","description":"","frontmatter":{},"headers":[],"relativePath":"translation/Debug_Command.md","filePath":"translation/Debug_Command.md"}`),a={name:`translation/Debug_Command.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="调试命令" tabindex="-1">调试命令 <a class="header-anchor" href="#调试命令" aria-label="Permalink to “调试命令”">​</a></h1><blockquote><p>翻译自原文档：<a href="https://osdn.net/projects/emuera/wiki/debugcom" target="_blank" rel="noreferrer">https://osdn.net/projects/emuera/wiki/debugcom</a></p></blockquote><p>调试命令默认处于禁用状态。</p><p>如果你想使用它，请在设置对话框中勾选<code>启用调试命令</code>，然后重新启动 Emuera。</p><p>该功能是没有调试模式的版本所提供的简易功能，建议使用<a href="./Debug_Mode.html">调试模式</a>进行调试。</p><p>在脚本运行过程中（游戏过程中），输入以 <code>@</code> 开头的文本，就会被识别为<strong>调试命令</strong>。</p><p>调试命令的格式与 <code>ERB</code> 相同，Emuera 会立即执行这些代码，就像在 <code>ERB</code> 脚本文件中运行代码一样。</p><p>是否区分大小写取决于 <code>emuera.config</code> 中的<code>忽略大小写</code>选项。</p><p>示例：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#6A9955;">;调试模式下</span></span>
<span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">MONEY</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 10000</span></span>
<span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">PRINTV</span><span style="color:#9CDCFE;"> FLAG</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">200</span></span>
<span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">PRINTFORM</span><span style="color:#D4D4D4;"> %</span><span style="color:#9CDCFE;">NAME</span><span style="color:#D4D4D4;">:</span><span style="color:#9CDCFE;">MASTER</span><span style="color:#D4D4D4;">%</span><span style="color:#DCDCAA;">的CFLAG</span><span style="color:#E6E6E6;">(</span><span style="color:#B5CEA8;">1</span><span style="color:#E6E6E6;">) </span><span style="color:#D4D4D4;">=</span><span style="color:#E6E6E6;"> {</span><span style="color:#9CDCFE;">CFLAG</span><span style="color:#D4D4D4;">:</span><span style="color:#9CDCFE;">MASTER</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">1</span><span style="color:#E6E6E6;">}</span></span>
<span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">ADDCHARA</span><span style="color:#B5CEA8;"> 1</span></span></code></pre></div><p>另外，直接输入变量或表达式也可以输出其值（<code>@</code> 后面的空格不是必需的）。</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@ </span><span style="color:#9CDCFE;">FLAG</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">200</span></span>
<span class="line"><span style="color:#E6E6E6;">@ </span><span style="color:#CE9178;">@&quot;</span><span style="color:#569CD6;">%</span><span style="color:#9CDCFE;">NAME</span><span style="color:#D4D4D4;">:</span><span style="color:#9CDCFE;">MASTER</span><span style="color:#569CD6;">%</span><span style="color:#CE9178;">的CFLAG(1) = </span><span style="color:#569CD6;">{</span><span style="color:#9CDCFE;">CFLAG</span><span style="color:#D4D4D4;">:</span><span style="color:#9CDCFE;">MASTER</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">1</span><span style="color:#569CD6;">}</span><span style="color:#CE9178;">&quot;</span></span></code></pre></div><p>但是，像 <code>IF</code>、<code>CALL</code> 这样会改变执行流程的指令，以及像 <code>INPUT</code>、<code>WAIT</code> 这样需要输入的指令无法使用。</p><p>以下是一些 <code>ERB</code> 中没有的指令：</p><ul><li><code>@REBOOT</code>：重新启动，并重新读取 <code>emuera.config</code>、<code>csv</code> 和 <code>erb</code> 文件。</li><li><code>@OUTPUT</code>：把当前窗口的日志输出到 <code>emuera.log</code>。如果文件已存在则覆盖。与 <code>OUTPUTLOG</code> 指令行为相同。</li><li><code>@EXIT</code>：退出 Emuera。与 <code>QUIT</code> 指令行为相同。</li><li><code>@CONFIG</code>：打开设置对话框。</li><li><code>@DEBUG</code>：打开调试对话框。仅在以<a href="./Debug_Mode.html">调试模式</a>启动时有效。</li></ul><p>除上述命令之外，也就是直接执行普通 <code>ERB</code> 指令时，<code>MASTER</code> 的 <code>NAME</code> 和 <code>CALLNAME</code> 会被强制改为<code>作弊者</code>（<code>イカサマ</code>）。</p><p>这是因为调试命令本身就是一种作弊手段，所以采取了防止滥用的措施。</p>`,17)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};